[Form]
public class OMGSftpFolderLookup extends FormRun
{
    str                         folderString;
    OMGSftpFolderLookup         sftpFolderLookup;

}

/// <summary>
/// Gets the caller class holding the connection parameters
/// </summary>
public void init()
{
    super();

    sftpFolderLookup = element.args().caller();
}

/// <summary>
/// Builds the directory tree
/// </summary>
public void run()
{
    OMGSftpFolderLookup::buildFolderTree_Sftp(FolderTreeControl,
                                              sftpFolderLookup.parmKeyVaultCertificateRef(),
                                              sftpFolderLookup.parmHostName(),
                                              sftpFolderLookup.parmPort(),
                                              sftpFolderLookup.parmUserName());

    super();
}

/// <summary>
/// Returns the selected directory to the calling control
/// </summary>
/// <param name = "_selectString">The selected directory</param>
public void closeSelect(str _selectString)
{
    super(_selectString);
}

/// <summary>
/// Sets the folderString
/// </summary>
/// <param name = "_OldItem">The old item</param>
/// <param name = "_NewItem">The new item</param>
/// <param name = "_how">How the selection was made</param>
public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
{
    super(_OldItem, _NewItem, _how);

    folderString = _NewItem.data();
}

/// <summary>
/// Calls the close select
/// </summary>
public void clicked()
{
    super();

    element.closeSelect(folderString);
}
